import { Injectable } from "@nestjs/common";
import type { CountryScopeDto } from "#/modules/reference/schema/dto/country-scope.dto.ts";
import type { HierarchyCollectionDto } from "#/modules/reference/schema/dto/hierarchy-collection.dto.ts";
import { ListHierarchiesUseCase } from "#/modules/reference/features/divisions/use-cases/list-hierarchies.repository.ts";

/**
 * The Divisions contract the controller calls, then its implementation: each method
 * delegates to the use case for that operation. Regenerated by Dryv; the use cases hold the logic.
 */
export abstract class ReferenceDivisionsService {
  abstract listHierarchies(input: CountryScopeDto): Promise<HierarchyCollectionDto>;
}

@Injectable()
export class ReferenceDivisionsServiceImpl extends ReferenceDivisionsService {
  constructor(private readonly listHierarchiesUseCase: ListHierarchiesUseCase) {
    super();
  }

  listHierarchies(input: CountryScopeDto): Promise<HierarchyCollectionDto> {
    return this.listHierarchiesUseCase.execute(input);
  }
}
